sys_variable_value.value:
(function() {
    var result = inputs.nask_result;

    if (!result) {
        outputs.match_result = 'No response received from the NASK skill.';
        return;
    }

    try {
        var data = (typeof result === 'string')
            ? JSON.parse(result)
            : result;

        var responseText =
            data.capabilities &&
            data.capabilities[Object.keys(data.capabilities)[0]] &&
            data.capabilities[Object.keys(data.capabilities)[0]].response;

        if (!responseText) {
            outputs.match_result = 'NASK response was empty.';
            return;
        }

        var responseData =
            (typeof responseText === 'string')
            ? JSON.parse(responseText)
            : responseText;

        outputs.match_result =
            responseData.model_output ||
            'NASK response did not contain model output.';

    } catch (e) {
        outputs.match_result =
            'Unable to process NASK response: ' + e.message;
    }
})();

